// src/core/level/types.ts
var ENVIRONNEMENTS = ["montagne", "neige", "desert", "automne", "ville", "pirate", "backrooms", "espace", "japon", "cyberpunk"];
var LIMITES = {
  pointsMin: 2,
  pointsMax: 150,
  objetsMax: 300,
  longueurMax: 3e3,
  largeurMin: 6,
  largeurMax: 20,
  hauteurMin: -50,
  hauteurMax: 150,
  ecartMin: 5,
  ecartMax: 150,
  nomMax: 40,
  auteurMax: 30,
  eauMax: 3,
  eauPointsMin: 3,
  eauPointsMax: 64,
  /** surface minimale d'un lac (m²) */
  eauAireMin: 100,
  /** hauteur de la surface d'un lac (m) */
  eauNiveauMin: -60,
  eauNiveauMax: 150,
  /** distance libre minimale (m) entre le bord de la route et un lac : la route reste au sec */
  eauMarge: 6
};

// src/core/env/eau.ts
var RIVE = 10;
var BERGE = 0.3;
var PENTE_FOND = 0.4;
var PROFONDEUR_MAX = 5;
var Lac = class {
  constructor(plan) {
    this.plan = plan;
    this.niveau = plan.niveau;
    this.px = Float64Array.from(plan.points, (p) => p.x);
    this.pz = Float64Array.from(plan.points, (p) => p.z);
    this.minX = Math.min(...this.px);
    this.maxX = Math.max(...this.px);
    this.minZ = Math.min(...this.pz);
    this.maxZ = Math.max(...this.pz);
  }
  minX;
  maxX;
  minZ;
  maxZ;
  niveau;
  px;
  pz;
  /** Le point est-il à moins de `marge` m de la boîte englobante ? (test rapide avant `distance`) */
  proche(x, z, marge) {
    return x >= this.minX - marge && x <= this.maxX + marge && z >= this.minZ - marge && z <= this.maxZ + marge;
  }
  /** Distance signée au bord du polygone (m) : > 0 à l'intérieur (eau), < 0 à l'extérieur. */
  distance(x, z) {
    const n = this.px.length;
    let dedans = false;
    let d2 = Infinity;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const ax = this.px[j], az = this.pz[j], bx = this.px[i], bz = this.pz[i];
      if (az > z !== bz > z && x < ax + (z - az) / (bz - az) * (bx - ax)) dedans = !dedans;
      const ex = bx - ax, ez = bz - az;
      const l2 = ex * ex + ez * ez;
      const t = l2 > 0 ? Math.max(0, Math.min(1, ((x - ax) * ex + (z - az) * ez) / l2)) : 0;
      const dx = x - (ax + t * ex), dz = z - (az + t * ez);
      const q = dx * dx + dz * dz;
      if (q < d2) d2 = q;
    }
    const d = Math.sqrt(d2);
    return dedans ? d : -d;
  }
  /** Hauteur du terrain modifiée par le lac : le fond descend sous la surface, la rive se raccorde en pente douce. */
  hauteur(x, z, terre) {
    if (!this.proche(x, z, RIVE)) return terre;
    const sd = this.distance(x, z);
    if (sd <= -RIVE) return terre;
    const rive = this.niveau + BERGE;
    if (sd <= 0) {
      const t = (sd + RIVE) / RIVE;
      const w = t * t * (3 - 2 * t);
      return terre + (rive - terre) * w;
    }
    return rive - Math.min(PROFONDEUR_MAX + BERGE, PENTE_FOND * sd);
  }
};
function problemesEau(eau, samples) {
  const out = [];
  (eau ?? []).forEach((plan, i) => {
    const lac = new Lac(plan);
    for (const sp of samples) {
      const marge = sp.w + LIMITES.eauMarge;
      if (!lac.proche(sp.x, sp.z, marge)) continue;
      if (lac.distance(sp.x, sp.z) > -marge) {
        out.push(`eau : le lac ${i + 1} touche la route vers ${Math.round(sp.s)} m (garde ${LIMITES.eauMarge} m au moins entre le bord de la route et l'eau).`);
        break;
      }
    }
  });
  return out;
}
function aire(points) {
  let a = 0;
  for (let i = 0, j = points.length - 1; i < points.length; j = i++) a += points[j].x * points[i].z - points[i].x * points[j].z;
  return Math.abs(a) / 2;
}
function autoIntersection(points) {
  const n = points.length;
  const cross = (o, a, b) => (a.x - o.x) * (b.z - o.z) - (a.z - o.z) * (b.x - o.x);
  for (let i = 0; i < n; i++) {
    const a = points[i], b = points[(i + 1) % n];
    for (let j = i + 1; j < n; j++) {
      if (j === i + 1 || i === 0 && j === n - 1) continue;
      const c = points[j], d = points[(j + 1) % n];
      if (cross(a, b, c) * cross(a, b, d) < 0 && cross(c, d, a) * cross(c, d, b) < 0) return true;
    }
  }
  return false;
}

// src/core/math/dmath.ts
var S1 = -0.16666666666666632;
var S2 = 0.00833333333332249;
var S3 = -1984126982985795e-19;
var S4 = 27557313707070068e-22;
var S5 = -25050760253406863e-24;
var S6 = 158969099521155e-24;
var C1 = 0.0416666666666666;
var C2 = -0.001388888888887411;
var C3 = 2480158728947673e-20;
var C4 = -27557314351390663e-23;
var C5 = 2087572321298175e-24;
var C6 = -11359647557788195e-27;
